CREATE TABLE `furnizori` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `denumire` varchar(50) NOT NULL,
  `codfiscal` varchar(10) NOT NULL,
  `regcom` varchar(14) DEFAULT NULL,
  `iban` varchar(24) DEFAULT NULL,
  `sucursala` varchar(20) DEFAULT NULL,
  `adresa` varchar(50) DEFAULT NULL,
  `localitate` varchar(20) DEFAULT NULL,
  `judet` varchar(15) DEFAULT NULL,
  `tel` varchar(12) DEFAULT NULL,
  `fax` varchar(12) DEFAULT NULL,
  `email` varchar(30) DEFAULT NULL,
  `idc` int(11) NOT NULL,
  `stare` varchar(8) NOT NULL,
  `dindata` date NOT NULL,
  `addedby` varchar(24) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1542 DEFAULT CHARSET=latin1;
