  `sursa_finantare` varchar(128) DEFAULT NULL,
  `id_procedura` int(11) NOT NULL,
  `luna_inceput` varchar(24) DEFAULT NULL,
  `luna_sfirsit` varchar(24) DEFAULT NULL,
  `mod_derulare` varchar(36) DEFAULT 'online',
  `responsabil` varchar(36) DEFAULT NULL,
  `id_compartiment` int(11) NOT NULL,
  `anplan` int(11) NOT NULL,
  `stare` varchar(36) DEFAULT NULL,
  `data_creere` date DEFAULT NULL,
  `data_modificare` date DEFAULT NULL,
  `rezerva` varchar(24) DEFAULT 'null',
  `observatii` varchar(128) DEFAULT NULL,
  `lock` int(11) DEFAULT '0',
  `from` int(11) DEFAULT '0',
  `to` int(11) DEFAULT '0',
  `artbug` varchar(10) DEFAULT '99.99.99',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3960 DEFAULT CHARSET=latin1;
